<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Admin;use App\Security;
Admin::requirePermission('settings.manage');$pdo=db();$error='';
function vipDeleteBannerImage(?string $path):void{$root=realpath(dirname(__DIR__).'/uploads/banners');$file=$path?realpath(dirname(__DIR__).'/'.$path):false;if($root&&$file&&str_starts_with($file,$root.DIRECTORY_SEPARATOR)&&is_file($file))@unlink($file);}
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();try{$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
if($action==='delete'){$q=$pdo->prepare("SELECT image_path FROM banners WHERE id=?");$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('العرض غير موجود.');$pdo->prepare("DELETE FROM banners WHERE id=?")->execute([$id]);vipDeleteBannerImage($old['image_path']);Admin::audit('banner.delete','banner',$id);header('Location: banners.php?deleted=1');exit;}
if($action!=='save')throw new RuntimeException('إجراء غير معروف.');
$title=trim((string)($_POST['title']??''));$subtitle=trim((string)($_POST['subtitle']??''));$alt=trim((string)($_POST['image_alt']??''));$label=trim((string)($_POST['button_label']??''));$url=trim((string)($_POST['button_url']??''));$active=isset($_POST['is_active'])?1:0;$sort=max(0,(int)($_POST['sort_order']??0));
if($title===''||mb_strlen($title)>220)throw new RuntimeException('عنوان العرض مطلوب (220 حرفاً كحد أقصى).');if($url!==''&&!preg_match('~^(https?://|/|#)~i',$url))throw new RuntimeException('رابط الزر غير صالح.');
$old=null;if($id){$q=$pdo->prepare("SELECT * FROM banners WHERE id=?");$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('العرض غير موجود.');}
$uploaded=[];if(isset($_FILES['images'])&&is_array($_FILES['images']['name']??null)){foreach($_FILES['images']['name'] as $i=>$filename){$err=$_FILES['images']['error'][$i]??UPLOAD_ERR_NO_FILE;if($err===UPLOAD_ERR_NO_FILE)continue;$uploaded[]=['name'=>$filename,'type'=>$_FILES['images']['type'][$i]??'','tmp_name'=>$_FILES['images']['tmp_name'][$i]??'','error'=>$err,'size'=>$_FILES['images']['size'][$i]??0];}}
if($id){
 $path=$old['image_path']??null;
 if($uploaded){$new=Admin::uploadImage($uploaded[0],'banners');if($path)vipDeleteBannerImage($path);$path=$new;}
 if(!$path)throw new RuntimeException('يجب رفع صورة للعرض.');
 $q=$pdo->prepare("UPDATE banners SET title=?,subtitle=?,image_path=?,image_alt=?,button_label=?,button_url=?,is_active=?,sort_order=? WHERE id=?");$q->execute([$title,$subtitle?:null,$path,$alt?:$title,$label?:null,$url?:null,$active,$sort,$id]);
 for($i=1;$i<count($uploaded);$i++){$new=Admin::uploadImage($uploaded[$i],'banners');$q=$pdo->prepare("INSERT INTO banners(title,subtitle,image_path,image_alt,button_label,button_url,is_active,sort_order) VALUES(?,?,?,?,?,?,?,?)");$q->execute([$title,$subtitle?:null,$new,$alt?:$title,$label?:null,$url?:null,$active,$sort+$i]);}
}else{
 if(!$uploaded)throw new RuntimeException('اختر صورة واحدة على الأقل للعرض.');
 foreach($uploaded as $i=>$file){$path=Admin::uploadImage($file,'banners');$q=$pdo->prepare("INSERT INTO banners(title,subtitle,image_path,image_alt,button_label,button_url,is_active,sort_order) VALUES(?,?,?,?,?,?,?,?)");$q->execute([$title,$subtitle?:null,$path,$alt?:$title,$label?:null,$url?:null,$active,$sort+$i]);$id=(int)$pdo->lastInsertId();}
}
Admin::audit('banner.save','banner',$id);header('Location: banners.php?saved=1');exit;
}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'تعذر حفظ العرض. تحقق من الصورة.';}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM banners WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query("SELECT * FROM banners ORDER BY sort_order,id")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>صور الواجهة | VIP 27</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1100px;margin:28px auto;padding:0 16px}.panel,.tile{background:#111;border:1px solid #49371c;border-radius:14px;padding:18px;margin:16px 0}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.fields label{display:block}.fields input{width:100%;padding:10px;background:#080808;color:#fff;border:1px solid #49371c;border-radius:8px;font:inherit}.items{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.tile{margin:0}.tile img{width:100%;height:155px;object-fit:cover;border-radius:8px}@media(max-width:650px){.items,.fields{grid-template-columns:1fr 1fr}}@media(max-width:430px){.items,.fields{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="text-link" href="index.php">← لوحة التحكم</a><h1>إدارة صور الواجهة الرئيسية</h1><p>تتبدل الصور المنشورة تلقائياً كل 3 ثوانٍ. يمكنك اختيار عدة صور دفعة واحدة؛ ستُضاف كشرائح مستقلة تتبدل تلقائياً كل 3 ثوانٍ. عند تعديل شريحة يمكنك استبدال صورتها أو إضافة صور أخرى.</p><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="notice">تم حفظ العرض.</div><?php elseif(isset($_GET['deleted'])):?><div class="notice">تم حذف العرض.</div><?php endif;?><section class="panel"><h2><?=$edit?'تعديل العرض':'إضافة صورة جديدة'?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="fields"><label>عنوان العرض<input name="title" required maxlength="220" value="<?=e($edit['title']??'معسلات VIP 27')?>"></label><label>الوصف<input name="subtitle" maxlength="500" value="<?=e($edit['subtitle']??'')?>"></label><label>الصور (JPG/PNG/WebP، حتى 5MB لكل صورة)<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple <?=$edit?'':'required'?>></label><label>وصف الصورة<input name="image_alt" maxlength="220" value="<?=e($edit['image_alt']??'معسلات VIP 27')?>"></label><label>نص الزر<input name="button_label" maxlength="80" value="<?=e($edit['button_label']??'تسوق الآن')?>"></label><label>رابط الزر<input name="button_url" maxlength="500" value="<?=e($edit['button_url']??'#products')?>"></label><label>الترتيب<input type="number" name="sort_order" min="0" value="<?=e((string)($edit['sort_order']??0))?>"></label><label><input type="checkbox" name="is_active" style="width:auto" <?=!isset($edit['is_active'])||(int)$edit['is_active']===1?'checked':''?>> نشر الصورة</label></div><p><button class="btn btn-gold">حفظ العرض</button> <a class="btn btn-outline" href="banners.php">إلغاء</a></p></form></section><section class="items"><?php foreach($rows as $row):?><article class="tile"><img src="../<?=e($row['image_path'])?>" alt="<?=e($row['image_alt']??$row['title'])?>"><h3><?=e($row['title'])?></h3><p><?=((int)$row['is_active']===1?'منشور':'متوقف')?> · الترتيب <?=(int)$row['sort_order']?></p><a class="btn btn-outline" href="?edit=<?=(int)$row['id']?>">تعديل</a><form method="post" onsubmit="return confirm('حذف العرض؟')"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn btn-outline">حذف</button></form></article><?php endforeach;?></section><?php if(!$rows):?><div class="empty-state">لم تتم إضافة صور بعد.</div><?php endif;?></main></body></html>